from . import builder


class Index:
    def __init__(self):
        self._idx = {}
        self._docs = 0

    def add(self, doc_id, text):
        self._docs += 1
        for batch in builder.build([(doc_id, text)]):
            builder.merge(self._idx, batch)

    def rebuild(self, pairs):
        self._idx = {}
        self._docs = 0
        for batch in builder.build(pairs):
            builder.merge(self._idx, batch)
        total = 0
        docs = set()
        for term_data in self._idx.values():
            for doc_id, positions in term_data.items():
                total += len(positions)
                docs.add(doc_id)
        self._docs = len(docs)
        return total

    def lookup(self, term):
        return sorted(self._idx.get(term, {}).keys())

    def doc_count(self):
        return self._docs

    def terms(self):
        return sorted(self._idx.keys())
