"""Exact money arithmetic."""
from decimal import Decimal, ROUND_HALF_UP, ROUND_FLOOR


class CurrencyMismatch(Exception):
    pass


class Money:
    def __init__(self, amount, currency='USD'):
        self.currency = currency
        self.cents = int(
            (Decimal(str(amount)) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
        )

    @classmethod
    def from_cents(cls, cents, currency='USD'):
        obj = cls.__new__(cls)
        obj.currency = currency
        obj.cents = int(cents)
        return obj

    def _check_currency(self, other):
        if self.currency != other.currency:
            raise CurrencyMismatch(
                f"Cannot operate on {self.currency} and {other.currency}"
            )

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return Money.from_cents(self.cents + other.cents, self.currency)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return Money.from_cents(self.cents - other.cents, self.currency)

    def __mul__(self, other):
        if isinstance(other, Money):
            raise TypeError("Cannot multiply Money by Money")
        multiplier = Decimal(str(other))
        new_cents = int(
            (Decimal(self.cents) * multiplier).quantize(
                Decimal('1'), rounding=ROUND_HALF_UP
            )
        )
        return Money.from_cents(new_cents, self.currency)

    def __neg__(self):
        return Money.from_cents(-self.cents, self.currency)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self.cents == other.cents and self.currency == other.currency

    def __lt__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return self.cents < other.cents

    def __hash__(self):
        return hash((self.cents, self.currency))

    def allocate(self, pairs):
        pairs = list(pairs)
        for key, weight in pairs:
            if weight <= 0:
                raise ValueError(f"Weight must be positive, got {weight}")

        if self.cents == 0:
            return {key: Money.from_cents(0, self.currency) for key, _ in pairs}

        total_weight = sum(Decimal(str(w)) for _, w in pairs)

        allocations = {}
        for key, weight in pairs:
            base = int(
                (Decimal(self.cents) * Decimal(str(weight)) / total_weight).quantize(
                    Decimal('1'), rounding=ROUND_FLOOR
                )
            )
            allocations[key] = base

        remainder = self.cents - sum(allocations.values())

        indexed = [(i, key, Decimal(str(weight))) for i, (key, weight) in enumerate(pairs)]
        indexed.sort(key=lambda x: (-x[2], x[0]))

        step = 1 if remainder > 0 else -1
        for i in range(abs(remainder)):
            allocations[indexed[i][1]] += step

        return {key: Money.from_cents(allocations[key], self.currency) for key, _ in pairs}

    def format(self):
        if self.cents < 0:
            abs_cents = -self.cents
            return f"-${abs_cents // 100}.{abs_cents % 100:02d}"
        return f"${self.cents // 100}.{self.cents % 100:02d}"
