"""Rolling windows."""


class Windowed:
    _peak_memory = 0

    def __init__(self, source, size, fn, key=None):
        if size <= 0:
            raise ValueError("size must be positive")
        self.source = source
        self.size = size
        self.fn = fn
        self.key = key

    def __iter__(self):
        buffers = {}
        for pair in self.source:
            if self.key is None:
                group_key = None
            else:
                group_key = self.key(pair)

            if group_key not in buffers:
                buffers[group_key] = []

            buffers[group_key].append(pair[1])

            current_len = len(buffers[group_key])
            if current_len > Windowed._peak_memory:
                Windowed._peak_memory = current_len

            if current_len == self.size:
                yield (group_key, self.fn(buffers[group_key]))
                buffers[group_key] = []

    @classmethod
    def peak_memory(cls):
        return cls._peak_memory


def summarise(source, size, fn, key=None):
    return list(Windowed(source, size, fn, key))
