import os
from .store import out_path


class Worker:
    def __init__(self, model, shards, out_dir, checkpoint_every=10):
        self.model = model
        self.shards = list(shards)
        self.out_dir = out_dir
        self.checkpoint_every = checkpoint_every
        self.total_inferred = 0
        self._skipped = 0
        self._done_list = []
        self._done_set = set()
        self._failed_set = set()
        os.makedirs(self.out_dir, exist_ok=True)
        self._load_done()
        self._load_failed()

    def _done_path(self):
        return os.path.join(self.out_dir, 'done.txt')

    def _failed_path(self):
        return os.path.join(self.out_dir, 'failed.txt')

    def _load_done(self):
        path = self._done_path()
        if os.path.exists(path):
            with open(path, 'r') as f:
                for line in f:
                    sid = line.strip()
                    if sid:
                        self._done_list.append(sid)
                        self._done_set.add(sid)

    def _load_failed(self):
        path = self._failed_path()
        if os.path.exists(path):
            with open(path, 'r') as f:
                for line in f:
                    sid = line.strip()
                    if sid:
                        self._failed_set.add(sid)

    def _flush_done(self):
        with open(self._done_path(), 'w') as f:
            for sid in self._done_list:
                f.write(sid + '\n')

    def _flush_failed(self):
        with open(self._failed_path(), 'w') as f:
            for sid in self._failed_set:
                f.write(sid + '\n')

    def _write_output(self, shard_id, result):
        op = out_path(self.out_dir, shard_id)
        os.makedirs(os.path.dirname(op), exist_ok=True)
        with open(op, 'w') as f:
            f.write(result)

    def run(self):
        self._skipped = 0
        completed_since_checkpoint = 0

        for shard_id in self.shards:
            if shard_id in self._done_set and os.path.exists(out_path(self.out_dir, shard_id)):
                self._skipped += 1
                continue

            try:
                result = self.model.infer(shard_id)
                self.total_inferred += 1
            except Exception:
                self.total_inferred += 1
                self._failed_set.add(shard_id)
                self._flush_failed()
                continue

            self._write_output(shard_id, result)
            self._done_list.append(shard_id)
            self._done_set.add(shard_id)
            self._failed_set.discard(shard_id)
            completed_since_checkpoint += 1

            if completed_since_checkpoint >= self.checkpoint_every:
                self._flush_done()
                completed_since_checkpoint = 0

        self._flush_done()
        self._flush_failed()

    def stats(self):
        done_count = 0
        for shard_id in self.shards:
            if shard_id in self._done_set and os.path.exists(out_path(self.out_dir, shard_id)):
                done_count += 1
        return {
            'total': len(self.shards),
            'done': done_count,
            'skipped': self._skipped,
            'failed': len(self._failed_set),
        }

    def retry_failed(self):
        failed_ids = list(self._failed_set)
        succeeded = 0

        for shard_id in failed_ids:
            try:
                result = self.model.infer(shard_id)
                self.total_inferred += 1
            except Exception:
                self.total_inferred += 1
                continue

            self._write_output(shard_id, result)
            self._failed_set.discard(shard_id)
            self._done_list.append(shard_id)
            self._done_set.add(shard_id)
            succeeded += 1

        self._flush_done()
        self._flush_failed()
        return succeeded
