"""Config merge."""

from types import MappingProxyType


class _Drop:
    def __repr__(self):
        return 'DROP'


DROP = _Drop()


def _deep_copy(obj):
    if isinstance(obj, dict):
        return {k: _deep_copy(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_deep_copy(v) for v in obj]
    return obj


def _remove_path(cfg, parts):
    cur = cfg
    for part in parts[:-1]:
        if not isinstance(cur, dict) or part not in cur:
            return
        cur = cur[part]
    if isinstance(cur, dict):
        cur.pop(parts[-1], None)


def _set_path(cfg, parts, value):
    cur = cfg
    for part in parts[:-1]:
        if part not in cur or not isinstance(cur[part], dict):
            cur[part] = {}
        cur = cur[part]
    cur[parts[-1]] = _deep_copy(value)


def _merge_recursive(base, layer, lists):
    for k, v in layer.items():
        if isinstance(k, str) and '.' in k:
            parts = k.split('.')
            if v is DROP:
                _remove_path(base, parts)
            else:
                _set_path(base, parts, v)
            continue

        if v is DROP:
            base.pop(k, None)
            continue

        if k in base:
            cur = base[k]
            if isinstance(cur, dict) and isinstance(v, dict):
                base[k] = _merge_recursive(cur, v, lists)
            elif isinstance(cur, list) and isinstance(v, list):
                if lists == 'replace':
                    base[k] = _deep_copy(v)
                elif lists == 'concat':
                    base[k] = cur + _deep_copy(v)
                elif lists == 'unique':
                    seen = []
                    for item in cur + _deep_copy(v):
                        if item not in seen:
                            seen.append(item)
                    base[k] = seen
                else:
                    base[k] = _deep_copy(v)
            else:
                base[k] = _deep_copy(v)
        else:
            base[k] = _deep_copy(v)

    return base


def merge(base, *layers, lists='replace'):
    out = _deep_copy(base)
    for layer in layers:
        out = _merge_recursive(out, layer, lists)
    return out


def deep_get(cfg, path, default=None):
    cur = cfg
    for part in path.split('.'):
        if not isinstance(cur, dict) or part not in cur:
            return default
        cur = cur[part]
    return cur


def deep_set(cfg, path, value):
    parts = path.split('.')
    out = _deep_copy(cfg)
    cur = out
    for part in parts[:-1]:
        if part not in cur or not isinstance(cur[part], dict):
            cur[part] = {}
        cur = cur[part]
    cur[parts[-1]] = _deep_copy(value)
    return out


def freeze(cfg):
    if isinstance(cfg, dict):
        return MappingProxyType({k: freeze(v) for k, v in cfg.items()})
    if isinstance(cfg, list):
        return tuple(freeze(v) for v in cfg)
    return cfg
